/* @autogenerated */
package net.civeira.phylax.common.infrastructure.exceptionmapper;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.time.Duration;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Supplier;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import jakarta.ws.rs.WebApplicationException;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.Response;
import net.civeira.phylax.common.exception.AbstractFailsException;
import net.civeira.phylax.common.exception.NotAllowedException;
import net.civeira.phylax.common.exception.PaymentRequiredException;
import net.civeira.phylax.common.exception.StepUpRequiredException;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.common.value.validation.AbstractFailList;
import net.civeira.phylax.testing.mock.LoggerChecker;

@DisplayName("Exception mappers across log levels")
class ExceptionMappersLoggingUnitTest {

  /**
   * Runs the mapping once with DEBUG, once with INFO/WARN and once with logging disabled, so every
   * log level guard is evaluated both ways. Returns the response of the last run.
   */
  static Response atEveryLevel(Object mapper, Supplier<Response> mapping) {
    try (LoggerChecker checker = LoggerChecker.bind(mapper)) {
      List<Consumer<LoggerChecker>> levels = List.of(LoggerChecker::setLevelToDebug,
          LoggerChecker::setLevelToInfo, LoggerChecker::setLevelToOff);
      Response last = null;
      for (Consumer<LoggerChecker> level : levels) {
        level.accept(checker);
        last = mapping.get();
      }
      return last;
    }
  }

  @SuppressWarnings("unchecked")
  private static String reason(Response response) {
    return ((Map<String, String>) response.getEntity()).get("reason");
  }

  @Nested
  @DisplayName("AbstractFailMapper")
  class AbstractFail {
    private final AbstractFailsException exception =
        new AbstractFailsException("invalid", new AbstractFailList()) {
          private static final long serialVersionUID = 1L;
        };

    @Test
    @DisplayName("Should answer 422 using the default locale when none is acceptable")
    void shouldUseDefaultLocale() {
      HttpHeaders headers = mock(HttpHeaders.class);
      when(headers.getAcceptableLanguages()).thenReturn(List.of());
      AbstractFailMapper mapper = new AbstractFailMapper(headers);

      assertEquals(422, atEveryLevel(mapper, () -> mapper.toResponse(exception)).getStatus());
    }

    @Test
    @DisplayName("Should answer 422 using the first acceptable locale")
    void shouldUseFirstAcceptableLocale() {
      HttpHeaders headers = mock(HttpHeaders.class);
      when(headers.getAcceptableLanguages()).thenReturn(List.of(Locale.forLanguageTag("es")));
      AbstractFailMapper mapper = new AbstractFailMapper(headers);

      assertEquals(422, mapper.toResponse(exception).getStatus());
    }
  }

  @Nested
  @DisplayName("NotAllowedExceptionMapper")
  class NotAllowed {

    @Test
    @DisplayName("Should answer 401 for anonymous callers")
    void shouldAnswer401ForAnonymous() {
      CurrentRequest request = mock(CurrentRequest.class);
      when(request.isAnonymous()).thenReturn(true);
      NotAllowedExceptionMapper mapper = new NotAllowedExceptionMapper(request);

      Response response =
          atEveryLevel(mapper, () -> mapper.toResponse(new NotAllowedException("nope")));

      assertEquals(401, response.getStatus());
      assertEquals("nope", reason(response));
    }

    @Test
    @DisplayName("Should answer 403 for authenticated callers")
    void shouldAnswer403ForAuthenticated() {
      CurrentRequest request = mock(CurrentRequest.class);
      when(request.isAnonymous()).thenReturn(false);
      NotAllowedExceptionMapper mapper = new NotAllowedExceptionMapper(request);

      assertEquals(403, mapper.toResponse(new NotAllowedException("nope")).getStatus());
    }
  }

  @Test
  @DisplayName("PaymentRequiredExceptionMapper should answer 402")
  void paymentRequiredShouldAnswer402() {
    PaymentRequiredExceptionMapper mapper = new PaymentRequiredExceptionMapper();

    Response response =
        atEveryLevel(mapper, () -> mapper.toResponse(new PaymentRequiredException("pay")));

    assertEquals(402, response.getStatus());
    assertEquals("pay", reason(response));
  }

  @Test
  @DisplayName("UncheckedIOExceptionMapper should answer 502")
  void uncheckedIoShouldAnswer502() {
    UncheckedIOExceptionMapper mapper = new UncheckedIOExceptionMapper();
    UncheckedIOException exception = new UncheckedIOException(new IOException("reset"));

    assertEquals(502, atEveryLevel(mapper, () -> mapper.toResponse(exception)).getStatus());
  }

  @Nested
  @DisplayName("StepUpRequiredExceptionMapper")
  class StepUp {

    @Test
    @DisplayName("Should fall back to the default ACR and tolerate a null message")
    void shouldFallBackToDefaultAcr() {
      StepUpRequiredExceptionMapper mapper = new StepUpRequiredExceptionMapper(" , ");

      Response response = atEveryLevel(mapper,
          () -> mapper.toResponse(new StepUpRequiredException(null, Duration.ofMinutes(5))));

      String challenge = response.getHeaderString(HttpHeaders.WWW_AUTHENTICATE);
      assertEquals(401, response.getStatus());
      assertTrue(challenge.contains("error_description=\"\""), challenge);
      assertTrue(challenge.contains("acr_values=\"urn:lugh:acr:mfa\""), challenge);
      assertTrue(challenge.contains("max_age=300"), challenge);
    }

    @Test
    @DisplayName("Should use the first configured ACR and escape the message")
    void shouldUseFirstConfiguredAcr() {
      StepUpRequiredExceptionMapper mapper = new StepUpRequiredExceptionMapper("urn:a, urn:b");

      String challenge = mapper.toResponse(new StepUpRequiredException("say \"hi\"\\"))
          .getHeaderString(HttpHeaders.WWW_AUTHENTICATE);

      assertTrue(challenge.contains("acr_values=\"urn:a\""), challenge);
      assertTrue(challenge.contains("say \\\"hi\\\"\\\\"), challenge);
      assertFalse(challenge.contains("max_age"), challenge);
    }
  }

  @Nested
  @DisplayName("ThrowableMapper")
  class Throwables {
    private final ThrowableMapper mapper = new ThrowableMapper();

    @Test
    @DisplayName("Should keep client error responses raised by JAX-RS")
    void shouldKeepClientErrors() {
      WebApplicationException exception = new WebApplicationException(404);
      assertSame(exception.getResponse(), mapper.toResponse(exception));
    }

    @Test
    @DisplayName("Should hide server error responses raised by JAX-RS")
    void shouldHideServerErrors() {
      Response response = mapper.toResponse(new WebApplicationException(503));
      assertEquals(500, response.getStatus());
      assertEquals("unknown", reason(response));
    }

    @Test
    @DisplayName("Should answer 500 when a web exception has no response")
    void shouldAnswer500WithoutResponse() {
      WebApplicationException exception = mock(WebApplicationException.class);
      when(exception.getResponse()).thenReturn(null);
      assertEquals(500, mapper.toResponse(exception).getStatus());
    }
  }
}
